style.css:
@-moz-document domain("youtube.com") {
/* -------- GLOBAL DARK MOON BACKGROUND -------- */
  body, ytd-app, #content, #page-manager {
    background: radial-gradient(circle at 50% 20%, #3a3f52 0%, #0f1118 70%) !important;
    color: #d9d9e6 !important;
  }

  /* -------- STARFIELD (noise speckles) -------- */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 99999;
    background: repeating-radial-gradient(
      circle,
      rgba(255,255,255,0.06) 0px,
      rgba(255,255,255,0.06) 1px,
      transparent 1px,
      transparent 3px
    );
    opacity: 0.25;
    mix-blend-mode: screen;
  }

  /* -------- MOON GLOW RIM -------- */
  body::after {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 99998;
    box-shadow:
      inset 0 0 120px rgba(200,210,255,0.17),
      inset 0 0 250px rgba(160,180,255,0.08);
    border-radius: 0;
  }

  /* -------- TOP BAR: cool moon-steel tone -------- */
  ytd-masthead {
    background: rgba(45, 50, 68, 0.9) !important;
    backdrop-filter: blur(6px);
    border-bottom: 1px solid rgba(255,255,255,0.1) !important;
  }

  /* -------- SEARCH BAR (silver lunar glow) -------- */
  #search-input input {
    background: rgba(255,255,255,0.08) !important;
    border: 1px solid rgba(255,255,255,0.2) !important;
    border-radius: 6px !important;
    color: #eee !important;
    box-shadow: 0 0 6px rgba(200,200,255,0.16);
  }

  #search-icon-legacy {
    background: rgba(255,255,255,0.13) !important;
  }

  /* -------- VIDEO CARDS (moon-surface texture illusion) -------- */
  ytd-rich-item-renderer,
  ytd-video-renderer {
    background: rgba(255,255,255,0.04) !important;
    border: 1px solid rgba(255,255,255,0.08) !important;
    border-radius: 10px !important;
    box-shadow:
      0 0 10px rgba(150,170,240,0.07),
      inset 0 0 10px rgba(0,0,0,0.2);
    backdrop-filter: blur(3px);
  }

  /* -------- TITLES: soft silver glow -------- */
  #video-title {
    color: #e7e8f7 !important;
    text-shadow: 
      0 0 6px rgba(200,210,255,0.4),
      0 0 2px rgba(150,170,255,0.4);
  }

  /* -------- LINKS -------- */
  a, yt-formatted-string {
    color: #dfe2ff !important;
  }

  /* -------- COMMENTS AREA -------- */
  #comments {
    background: rgba(255,255,255,0.03) !important;
    border: 1px solid rgba(255,255,255,0.06) !important;
    border-radius: 12px !important;
    box-shadow: inset 0 0 12px rgba(200,220,255,0.05);
  }

  /* -------- BUTTONS: moon metal -------- */
  ytd-subscribe-button-renderer button {
    background: rgba(255,255,255,0.1) !important;
    color: white !important;
    border-radius: 8px !important;
    border: 1px solid rgba(255,255,255,0.2) !important;
    box-shadow: 0 0 8px rgba(180,190,255,0.3);
  }

  /* -------- SCROLLBAR -------- */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(160,170,210,0.4) !important;
  }
  ::-webkit-scrollbar-track {
    background: rgba(30,32,42,0.9) !important;
  }
}
